#include "../src/game/flying_stage.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::PlayerPayload p;shin::initialize_player_payload(p,4,4);shin::FlyingStageMotion fly;shin::InputState in;shin::IndexedSurface f(640,480);fly.tick(p,in,0,0,1500,30,false,a,f);assert(p.at(12)==128&&p.at(8)==131);in.message(0x100,38);fly.tick(p,in,0,0,1500,30,false,a,f);assert(p.at(0x58)==-11&&p.at(12)==117);in.message(0x101,38);in.message(0x100,32);for(int i=0;i<3;++i)fly.tick(p,in,0,0,1500,30,false,a,f);assert(fly.shots.size()==3);fly.tick(p,in,0,0,1500,30,false,a,f);assert(fly.shots.size()==3);shin::game::SceneCamera c;shin::FlyingStageMotion::camera(c,p,1500,30,false);assert(c.offset_x==3);in.message(0x101,32);int lives=p.at(0x8c);assert(fly.hurt(p));assert(fly.sounds.size()==1&&fly.sounds[0]==0x4752e8);assert(!fly.hurt(p));assert(fly.sounds.size()==1);for(int i=0;i<10;++i)fly.tick(p,in,0,0,1500,30,false,a,f);assert(p.at(0x8c)==lives-1&&p.at(0xb8)>0);assert(!fly.hurt(p));shin::game::EntityPayload shot;shot.at(4)=100;shot.at(8)=100;assert(shin::FlyingStageMotion::shot_hits(shot,{0,0,50,50},105,105));assert(!shin::FlyingStageMotion::shot_hits(shot,{0,0,50,50},105,105));}
